INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (138, 'hotOrcamentoStatus', 'Mount+loadStatus da tela Orcamento em 1 ida (GESTORES,CRS,CICLO_ABERTO,STATUS,MODELOS). Params: crId,gestorId (0 = sem status).', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''EMAIL'',t.EMAIL,''ATIVO'',t.ATIVO)) FROM GESTOR t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS GESTORES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''EMPRESA_ID'',t.EMPRESA_ID,''ATIVO'',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CRS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''ANO'',t.ANO,''STATUS'',t.STATUS,''CRIADO_EM'',t.CRIADO_EM,''VERSAO_ATUAL'',t.VERSAO_ATUAL,''ULTIMO_MES_REALIZADO'',t.ULTIMO_MES_REALIZADO,''VERSAO_CONTROLE'',t.VERSAO_CONTROLE,''VERSAO_ORIGEM_ID'',t.VERSAO_ORIGEM_ID,''CRIADO_POR'',t.CRIADO_POR)) FROM CICLO t WHERE t.ID = (SELECT ID FROM CICLO WHERE STATUS != ''FECHADO'' ORDER BY ANO DESC, ID DESC LIMIT 1)),JSON_ARRAY()) AS CICLO_ABERTO,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''GESTOR_ID'',t.GESTOR_ID,''CR_ID'',t.CR_ID,''STATUS'',t.STATUS,''COMENTARIO'',t.COMENTARIO,''ATUALIZADO_EM'',t.ATUALIZADO_EM,''DRIVERS_CONFIRMADOS'',t.DRIVERS_CONFIRMADOS)) FROM ORCAMENTO_STATUS t WHERE t.CICLO_ID = (SELECT ID FROM CICLO WHERE STATUS != ''FECHADO'' ORDER BY ANO DESC, ID DESC LIMIT 1) AND t.CR_ID = {{crId}} AND t.GESTOR_ID = {{gestorId}}),JSON_ARRAY()) AS STATUS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CR_ID'',x.CR_ID,''TOTAL'',x.TOTAL)) FROM (SELECT crc.CR_ID, COUNT(DISTINCT d.NOME) AS TOTAL FROM CR_CONTA crc LEFT JOIN CONTA_DRIVER_EXCECAO cde ON cde.CR_ID = crc.CR_ID AND cde.CONTA_ID = crc.CONTA_ID AND cde.ATIVO = true LEFT JOIN CONTA_DRIVER cd ON cd.CONTA_ID = crc.CONTA_ID LEFT JOIN DRIVERS d ON d.ID = COALESCE(cde.PACOTE_ID, cd.PACOTE_ID, cde.DRIVER_ID, cd.DRIVER_ID) WHERE crc.CR_ID = {{crId}} AND crc.ATIVO = true AND d.ID IS NOT NULL AND d.ATIVO = ''true'' GROUP BY crc.CR_ID) x),JSON_ARRAY()) AS MODELOS', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
